     1→import fs from 'fs';
     2→import path from 'path';
     3→import { parse as parseYaml } from 'yaml';
     4→import type {
     5→  CatalogItem,
     6→  Catalog,
     7→  CatalogStats,
     8→  CatalogConfig,
     9→  ContentKind,
    10→  ContentSource,
    11→  Ecosystem,
    12→} from '@/lib/types/catalog';
    13→import { parseFrontmatter, nameFromFilename } from './frontmatter';
    14→
    15→const PROJECT_ROOT = process.cwd();
    16→
    17→const DEFAULT_CONFIG: CatalogConfig = {
    18→  featuredIds: [],
    19→  scanDirectories: [
    20→    { path: 'copilot-contribution', source: 'builtin', ecosystem: 'copilot' },
    21→    { path: 'awesome-copilot', source: 'awesome-copilot', ecosystem: 'copilot' },
    22→    { path: 'user-content', source: 'user' },
    23→  ],
    24→};
    25→
    26→// File extension patterns → content kind
    27→const KIND_PATTERNS: [RegExp, ContentKind][] = [
    28→  [/\.agent\.md$/i, 'agent'],
    29→  [/\.prompt\.md$/i, 'prompt'],
    30→  [/\.instructions\.md$/i, 'instruction'],
    31→  [/\.collection\.(yml|yaml)$/i, 'collection'],
    32→];
    33→
    34→// Skills directories to scan (VS Code 1.109+ / Claude compatible)
    35→const SKILLS_DIRECTORIES = [
    36→  '.github/skills',
    37→  '.claude/skills',
    38→  '.copilot/skills',
    39→];
    40→
    41→let cachedCatalog: Catalog | null = null;
    42→
    43→function loadConfig(): CatalogConfig {
    44→  const configPath = path.join(PROJECT_ROOT, 'catalog-config.json');
    45→  try {
    46→    const raw = fs.readFileSync(configPath, 'utf-8');
    47→    const parsed = JSON.parse(raw);
    48→    return { ...DEFAULT_CONFIG, ...parsed };
    49→  } catch {
    50→    return DEFAULT_CONFIG;
    51→  }
    52→}
    53→
    54→function detectKind(filename: string): ContentKind | null {
    55→  for (const [pattern, kind] of KIND_PATTERNS) {
    56→    if (pattern.test(filename)) return kind;
    57→  }
    58→  // CLAUDE.md files are instructions for Claude Code
    59→  if (/^CLAUDE\.md$/i.test(filename)) return 'instruction';
    60→  // SKILL.md files are agent skills (VS Code 1.109+ / Claude compatible)
    61→  if (/^SKILL\.md$/i.test(filename)) return 'skill';
    62→  return null;
    63→}
    64→
    65→function detectEcosystem(filePath: string, source: ContentSource, dirEcosystem?: Ecosystem): Ecosystem {
    66→  if (dirEcosystem) return dirEcosystem;
    67→
    68→  const lower = filePath.toLowerCase();
    69→  if (lower.includes('claude-code') || lower.includes('claude.md')) return 'claude-code';
    70→  if (lower.includes('copilot')) return 'copilot';
    71→  return 'universal';
    72→}
    73→
    74→function slugFromPath(filePath: string): string {
    75→  const basename = path.basename(filePath);
    76→  return basename
    77→    .replace(/\.(agent|prompt|instructions|collection)\.(md|yml|yaml)$/i, '')
    78→    .replace(/[^a-zA-Z0-9-]/g, '-')
    79→    .replace(/-+/g, '-')
    80→    .replace(/^-|-$/g, '')
    81→    .toLowerCase();
    82→}
    83→
    84→function walkDirectory(dir: string, extensions: string[]): string[] {
    85→  const results: string[] = [];
    86→
    87→  if (!fs.existsSync(dir)) return results;
    88→
    89→  const entries = fs.readdirSync(dir, { withFileTypes: true });
    90→  for (const entry of entries) {
    91→    const fullPath = path.join(dir, entry.name);
    92→
    93→    // Skip hidden directories and node_modules
    94→    if (entry.name.startsWith('.') && entry.isDirectory()) continue;
    95→    if (entry.name === 'node_modules') continue;
    96→    if (entry.name === '.git') continue;
    97→
    98→    if (entry.isDirectory()) {
    99→      results.push(...walkDirectory(fullPath, extensions));
   100→    } else if (extensions.some(ext => entry.name.endsWith(ext))) {
   101→      results.push(fullPath);
   102→    } else if (/^CLAUDE\.md$/i.test(entry.name)) {
   103→      results.push(fullPath);
   104→    } else if (/^SKILL\.md$/i.test(entry.name)) {
   105→      results.push(fullPath);
   106→    }
   107→  }
   108→
   109→  return results;
   110→}
   111→
   112→function parseFile(
   113→  filePath: string,
   114→  source: ContentSource,
   115→  dirEcosystem?: Ecosystem,
   116→  featuredIds: string[] = []
   117→): CatalogItem | null {
   118→  try {
   119→    const raw = fs.readFileSync(filePath, 'utf-8');
   120→    const relativePath = path.relative(PROJECT_ROOT, filePath);
   121→    const filename = path.basename(filePath);
   122→    const kind = detectKind(filename);
   123→
   124→    if (!kind) return null;
   125→
   126→    // Handle YAML collection files
   127→    if (kind === 'collection' && (filename.endsWith('.yml') || filename.endsWith('.yaml'))) {
   128→      try {
   129→        const parsed = parseYaml(raw);
   130→        const id = parsed.id || slugFromPath(filePath);
   131→        return {
   132→          id,
   133→          kind,
   134→          ecosystem: detectEcosystem(relativePath, source, dirEcosystem),
   135→          source,
   136→          name: parsed.name || nameFromFilename(filename),
   137→          description: parsed.description || '',
   138→          filePath: relativePath,
   139→          rawContent: raw,
   140→          tags: parsed.tags || [],
   141→          featured: featuredIds.includes(id) || source === 'builtin',
   142→        };
   143→      } catch {
   144→        return null;
   145→      }
   146→    }
   147→
   148→    // Handle markdown files with frontmatter
   149→    const { frontmatter, body } = parseFrontmatter(raw);
   150→    const id = slugFromPath(filePath);
   151→
   152→    return {
   153→      id,
   154→      kind,
   155→      ecosystem: detectEcosystem(relativePath, source, dirEcosystem),
   156→      source,
   157→      name: (frontmatter.name as string) || nameFromFilename(filename),
   158→      description: (frontmatter.description as string) || extractFirstParagraph(body),
   159→      filePath: relativePath,
   160→      rawContent: raw,
   161→      tags: Array.isArray(frontmatter.tags) ? frontmatter.tags as string[] : [],
   162→      model: frontmatter.model as string | undefined,
   163→      tools: Array.isArray(frontmatter.tools) ? frontmatter.tools as string[] : undefined,
   164→      featured: featuredIds.includes(id) || source === 'builtin',
   165→    };
   166→  } catch {
   167→    return null;
   168→  }
   169→}
   170→
   171→function extractFirstParagraph(body: string): string {
   172→  const lines = body.split('\n');
   173→  const paragraphLines: string[] = [];
   174→
   175→  for (const line of lines) {
   176→    const trimmed = line.trim();
   177→    if (trimmed.startsWith('#')) continue;
   178→    if (trimmed === '' && paragraphLines.length > 0) break;
   179→    if (trimmed !== '') paragraphLines.push(trimmed);
   180→  }
   181→
   182→  const result = paragraphLines.join(' ');
   183→  return result.length > 200 ? result.slice(0, 197) + '...' : result;
   184→}
   185→
   186→function computeStats(items: CatalogItem[]): CatalogStats {
   187→  const stats: CatalogStats = {
   188→    totalItems: items.length,
   189→    byKind: { agent: 0, prompt: 0, instruction: 0, collection: 0, skill: 0, tool: 0, repo: 0 },
   190→    byEcosystem: { copilot: 0, 'claude-code': 0, universal: 0 },
   191→    bySource: { builtin: 0, 'awesome-copilot': 0, community: 0, user: 0 },
   192→  };
   193→
   194→  for (const item of items) {
   195→    stats.byKind[item.kind]++;
   196→    stats.byEcosystem[item.ecosystem]++;
   197→    stats.bySource[item.source]++;
   198→  }
   199→
   200→  return stats;
   201→}
   202→
   203→/** Scan for CLAUDE.md files at project root and in .claude/ directories */
   204→function scanClaudeCodeContent(featuredIds: string[]): CatalogItem[] {
   205→  const items: CatalogItem[] = [];
   206→
   207→  // Check project root for CLAUDE.md
   208→  const claudeMdPath = path.join(PROJECT_ROOT, 'CLAUDE.md');
   209→  if (fs.existsSync(claudeMdPath)) {
   210→    const item = parseFile(claudeMdPath, 'user', 'claude-code', featuredIds);
   211→    if (item) items.push(item);
   212→  }
   213→
   214→  // Check .claude/ directory for commands, hooks, etc.
   215→  const claudeDir = path.join(PROJECT_ROOT, '.claude');
   216→  if (fs.existsSync(claudeDir)) {
   217→    const files = walkDirectory(claudeDir, ['.md', '.yml', '.yaml']);
   218→    for (const file of files) {
   219→      // Skip plans directory (internal)
   220→      if (file.includes('/plans/')) continue;
   221→      const item = parseFile(file, 'user', 'claude-code', featuredIds);
   222→      if (item) items.push(item);
   223→    }
   224→  }
   225→
   226→  return items;
   227→}
   228→
   229→export function scanCatalog(forceRefresh = false): Catalog {
   230→  if (cachedCatalog && !forceRefresh) return cachedCatalog;
   231→
   232→  const config = loadConfig();
   233→  const items: CatalogItem[] = [];
   234→  const seenIds = new Set<string>();
   235→
   236→  // Scan configured directories
   237→  for (const dir of config.scanDirectories) {
   238→    const fullDir = path.join(PROJECT_ROOT, dir.path);
   239→    const files = walkDirectory(fullDir, ['.agent.md', '.prompt.md', '.instructions.md', '.collection.yml', '.collection.yaml']);
   240→
   241→    for (const file of files) {
   242→      const item = parseFile(file, dir.source, dir.ecosystem, config.featuredIds);
   243→      if (item && !seenIds.has(item.id)) {
   244→        seenIds.add(item.id);
   245→        items.push(item);
   246→      }
   247→    }
   248→  }
   249→
   250→  // Auto-detect Claude Code content
   251→  const claudeItems = scanClaudeCodeContent(config.featuredIds);
   252→  for (const item of claudeItems) {
   253→    if (!seenIds.has(item.id)) {
   254→      seenIds.add(item.id);
   255→      items.push(item);
   256→    }
   257→  }
   258→
   259→  // Scan skills directories (VS Code 1.109+ / Claude compatible)
   260→  for (const skillsDir of SKILLS_DIRECTORIES) {
   261→    const fullSkillsDir = path.join(PROJECT_ROOT, skillsDir);
   262→    if (!fs.existsSync(fullSkillsDir)) continue;
   263→    const skillFiles = walkDirectory(fullSkillsDir, ['.md']);
   264→    for (const file of skillFiles) {
   265→      if (!/SKILL\.md$/i.test(path.basename(file))) continue;
   266→      const item = parseFile(file, 'user', undefined, config.featuredIds);
   267→      if (item && !seenIds.has(item.id)) {
   268→        seenIds.add(item.id);
   269→        items.push(item);
   270→      }
   271→    }
   272→  }
   273→
   274→  // Sort: featured first, then alphabetical
   275→  items.sort((a, b) => {
   276→    if (a.featured !== b.featured) return a.featured ? -1 : 1;
   277→    return a.name.localeCompare(b.name);
   278→  });
   279→
   280→  cachedCatalog = {
   281→    items,
   282→    stats: computeStats(items),
   283→    lastScanned: new Date().toISOString(),
   284→  };
   285→
   286→  return cachedCatalog;
   287→}
   288→
   289→export function getCatalogByKind(kind: ContentKind): CatalogItem[] {
   290→  const catalog = scanCatalog();
