     1→import type { Frontmatter } from '@/lib/types/catalog';
     2→
     3→/**
     4→ * Parse YAML frontmatter from a markdown file's content.
     5→ * Frontmatter is delimited by --- at the start and end.
     6→ */
     7→export function parseFrontmatter(content: string): { frontmatter: Frontmatter; body: string } {
     8→  const trimmed = content.trimStart();
     9→
    10→  if (!trimmed.startsWith('---')) {
    11→    return { frontmatter: {}, body: content };
    12→  }
    13→
    14→  const endIndex = trimmed.indexOf('---', 3);
    15→  if (endIndex === -1) {
    16→    return { frontmatter: {}, body: content };
    17→  }
    18→
    19→  const raw = trimmed.slice(3, endIndex).trim();
    20→  const body = trimmed.slice(endIndex + 3).trim();
    21→  const frontmatter: Frontmatter = {};
    22→
    23→  for (const line of raw.split('\n')) {
    24→    const colonIndex = line.indexOf(':');
    25→    if (colonIndex === -1) continue;
    26→
    27→    const key = line.slice(0, colonIndex).trim();
    28→    let value = line.slice(colonIndex + 1).trim();
    29→
    30→    // Remove surrounding quotes
    31→    if ((value.startsWith("'") && value.endsWith("'")) ||
    32→        (value.startsWith('"') && value.endsWith('"'))) {
    33→      value = value.slice(1, -1);
    34→    }
    35→
    36→    // Parse arrays: ['item1', 'item2']
    37→    if (value.startsWith('[') && value.endsWith(']')) {
    38→      const inner = value.slice(1, -1);
    39→      frontmatter[key] = inner
    40→        .split(',')
    41→        .map(s => s.trim().replace(/^['"]|['"]$/g, ''))
    42→        .filter(Boolean);
    43→    } else {
    44→      frontmatter[key] = value;
    45→    }
    46→  }
    47→
    48→  return { frontmatter, body };
    49→}
    50→
    51→/**
    52→ * Derive a human-readable name from a filename.
    53→ * "context-architect.agent.md" -> "Context Architect"
    54→ */
    55→export function nameFromFilename(filename: string): string {
    56→  return filename
    57→    .replace(/\.(agent|prompt|instructions|collection)\.(md|yml|yaml)$/i, '')
    58→    .replace(/[-_]/g, ' ')
    59→    .replace(/\b\w/g, c => c.toUpperCase())
    60→    .trim();
    61→}
