     1→/**
     2→ * Tokalator - Cost Calculation & Economic Model Library
     3→ * Based on Bergemann, Bonatti, Smolin (2025) "The Economics of Large Language Models"
     4→ * 
     5→ * Cobb-Douglas Quality Function: Q = X^α × Y^β × (b + Z)^γ
     6→ * where:
     7→ *   X = input tokens
     8→ *   Y = output tokens  
     9→ *   Z = cache/fine-tuning tokens
    10→ *   α, β, γ = sensitivity parameters (α + β + γ < 1)
    11→ *   b = base model quality
    12→ */
    13→
    14→// ============================================
    15→// TYPES
    16→// ============================================
    17→
    18→export interface TokenUsage {
    19→  inputTokens: number;
    20→  outputTokens: number;
    21→  cacheWriteTokens?: number;
    22→  cacheReadTokens?: number;
    23→  promptLength?: number; // For Sonnet's tiered pricing
    24→}
    25→
    26→export interface ServiceUsage {
    27→  webSearches?: number;
    28→  codeExecMinutes?: number;
    29→}
    30→
    31→export interface PricingTier {
    32→  inputCostPerMTok: number;
    33→  outputCostPerMTok: number;
    34→  cacheWriteCostPerMTok: number;
    35→  cacheReadCostPerMTok: number;
    36→  promptTokenThreshold?: number | null;
    37→}
    38→
    39→export interface ModelParams {
    40→  baseQuality: number; // b
    41→  alphaParam: number;  // α
    42→  betaParam: number;   // β
    43→  gammaParam: number;  // γ
    44→}
    45→
    46→export interface CostBreakdown {
    47→  inputCost: number;
    48→  outputCost: number;
    49→  cacheWriteCost: number;
    50→  cacheReadCost: number;
    51→  webSearchCost: number;
    52→  codeExecCost: number;
    53→  totalCost: number;
    54→}
    55→
    56→export interface QualityMetrics {
    57→  qualityScore: number;
    58→  costPerQualityUnit: number;
    59→  marginalCostInput: number;
    60→  marginalCostOutput: number;
    61→}
    62→
    63→// ============================================
    64→// CONSTANTS - Anthropic Pricing (February 2026)
    65→// ============================================
    66→
