   144→
   145→// ============================================
   146→// COST CALCULATION FUNCTIONS
   147→// ============================================
   148→
   149→/**
   150→ * Get the applicable pricing tier based on prompt length
   151→ */
   152→export function getPricingTier(
   153→  modelName: string,
   154→  promptLength?: number
   155→): PricingTier {
   156→  const pricing = ANTHROPIC_PRICING[modelName as keyof typeof ANTHROPIC_PRICING];
   157→  if (!pricing) {
   158→    throw new Error(`Unknown model: ${modelName}`);
   159→  }
   160→
   161→  // Check for tiered pricing (Sonnet)
   162→  if ('threshold' in pricing && promptLength !== undefined) {
   163→    if (promptLength > pricing.threshold) {
   164→      return pricing.extended;
   165→    }
   166→  }
   167→
   168→  return pricing.standard;
   169→}
   170→
   171→/**
   172→ * Calculate token costs
   173→ */
   174→export function calculateTokenCost(
   175→  usage: TokenUsage,
   176→  pricing: PricingTier
   177→): Omit<CostBreakdown, 'webSearchCost' | 'codeExecCost' | 'totalCost'> {
   178→  const inputCost = (usage.inputTokens / 1_000_000) * pricing.inputCostPerMTok;
   179→  const outputCost = (usage.outputTokens / 1_000_000) * pricing.outputCostPerMTok;
   180→  const cacheWriteCost = ((usage.cacheWriteTokens || 0) / 1_000_000) * pricing.cacheWriteCostPerMTok;
   181→  const cacheReadCost = ((usage.cacheReadTokens || 0) / 1_000_000) * pricing.cacheReadCostPerMTok;
   182→
   183→  return {
   184→    inputCost,
   185→    outputCost,
   186→    cacheWriteCost,
   187→    cacheReadCost,
   188→  };
   189→}
   190→
   191→/**
   192→ * Calculate service costs (web search, code execution)
   193→ */
   194→export function calculateServiceCost(usage: ServiceUsage): { webSearchCost: number; codeExecCost: number } {
   195→  const webSearchCost = ((usage.webSearches || 0) / 1000) * SERVICE_PRICING.webSearch.costPer1K;
   196→  const codeExecCost = ((usage.codeExecMinutes || 0) / 60) * SERVICE_PRICING.codeExecution.costPerHour;
   197→
   198→  return { webSearchCost, codeExecCost };
   199→}
   200→
   201→/**
   202→ * Calculate total cost breakdown
   203→ */
   204→export function calculateCost(
   205→  modelName: string,
   206→  tokenUsage: TokenUsage,
   207→  serviceUsage?: ServiceUsage
   208→): CostBreakdown {
   209→  const pricing = getPricingTier(modelName, tokenUsage.promptLength);
   210→  const tokenCosts = calculateTokenCost(tokenUsage, pricing);
   211→  const serviceCosts = calculateServiceCost(serviceUsage || {});
   212→
   213→  const totalCost =
   214→    tokenCosts.inputCost +
   215→    tokenCosts.outputCost +
   216→    tokenCosts.cacheWriteCost +
   217→    tokenCosts.cacheReadCost +
   218→    serviceCosts.webSearchCost +
   219→    serviceCosts.codeExecCost;
   220→
   221→  return {
   222→    ...tokenCosts,
   223→    ...serviceCosts,
   224→    totalCost,
   225→  };
   226→}
   227→
   228→// ============================================
   229→// ECONOMIC MODEL FUNCTIONS (Cobb-Douglas)
   230→// ============================================
   231→
   232→/**
   233→ * Calculate quality score using Cobb-Douglas production function
   234→ * Q = X^α × Y^β × (b + Z)^γ
   235→ */
   236→export function calculateQuality(
   237→  inputTokens: number,
   238→  outputTokens: number,
   239→  cacheTokens: number,
   240→  params: ModelParams
   241→): number {
   242→  const { baseQuality, alphaParam, betaParam, gammaParam } = params;
   243→  
   244→  // Normalize tokens to reasonable scale (per 1K)
   245→  const X = inputTokens / 1000;
   246→  const Y = outputTokens / 1000;
   247→  const Z = cacheTokens / 1000;
   248→
   249→  if (X <= 0 || Y <= 0) return 0;
   250→
   251→  const quality = Math.pow(X, alphaParam) * 
   252→                  Math.pow(Y, betaParam) * 
   253→                  Math.pow(baseQuality + Z, gammaParam);
   254→
   255→  return quality;
   256→}
   257→
   258→/**
   259→ * Calculate minimum cost to achieve target quality
   260→ * From Lemma 4 in the paper
   261→ */
   262→export function calculateMinCostForQuality(
   263→  targetQuality: number,
   264→  modelName: string,
   265→  useCaching: boolean = false
   266→): { inputTokens: number; outputTokens: number; cacheTokens: number; cost: number } {
   267→  const params = MODEL_PARAMS[modelName];
   268→  const pricing = getPricingTier(modelName);
   269→  
   270→  if (!params) {
   271→    throw new Error(`Unknown model: ${modelName}`);
   272→  }
   273→
   274→  const { baseQuality, alphaParam, betaParam, gammaParam } = params;
   275→  const { inputCostPerMTok, outputCostPerMTok, cacheWriteCostPerMTok } = pricing;
   276→
   277→  // Cost coefficients (per 1K tokens)
   278→  const cx = inputCostPerMTok / 1000;
   279→  const cy = outputCostPerMTok / 1000;
   280→  const cz = cacheWriteCostPerMTok / 1000;
   281→
   282→  if (!useCaching) {
   283→    // Without caching: solve for optimal X, Y given Z = 0
   284→    // From the paper's closed-form solution
   285→    const sumAB = alphaParam + betaParam;
   286→    
   287→    const factor = Math.pow(targetQuality / Math.pow(baseQuality, gammaParam), 1 / sumAB);
   288→    const ratioXY = (alphaParam * cy) / (betaParam * cx);
   289→    
   290→    const X = factor * Math.pow(ratioXY, betaParam / sumAB);
   291→    const Y = factor * Math.pow(1 / ratioXY, alphaParam / sumAB);
   292→    
   293→    const cost = cx * X + cy * Y;
   294→    
   295→    return {
   296→      inputTokens: Math.round(X * 1000),
   297→      outputTokens: Math.round(Y * 1000),
   298→      cacheTokens: 0,
   299→      cost: cost * 1000, // Convert back to per-MTok basis
   300→    };
   301→  } else {
   302→    // With caching: solve for optimal X, Y, Z
   303→    const sumABG = alphaParam + betaParam + gammaParam;
   304→    
   305→    const factor = Math.pow(targetQuality, 1 / sumABG);
   306→    
   307→    // Optimal ratios from paper
   308→    const X = (alphaParam / cx) * Math.pow(cx / alphaParam, alphaParam / sumABG) *
   309→              Math.pow(cy / betaParam, betaParam / sumABG) *
   310→              Math.pow(cz / gammaParam, gammaParam / sumABG) * factor;
   311→    
   312→    const Y = (betaParam / cy) * Math.pow(cx / alphaParam, alphaParam / sumABG) *
   313→              Math.pow(cy / betaParam, betaParam / sumABG) *
   314→              Math.pow(cz / gammaParam, gammaParam / sumABG) * factor;
   315→    
   316→    const Z = (gammaParam / cz) * Math.pow(cx / alphaParam, alphaParam / sumABG) *
   317→              Math.pow(cy / betaParam, betaParam / sumABG) *
   318→              Math.pow(cz / gammaParam, gammaParam / sumABG) * factor - baseQuality;
   319→    
   320→    const cost = cx * X + cy * Y + cz * Math.max(0, Z);
   321→    
   322→    return {
   323→      inputTokens: Math.round(X * 1000),
   324→      outputTokens: Math.round(Y * 1000),
   325→      cacheTokens: Math.round(Math.max(0, Z) * 1000),
   326→      cost: cost * 1000,
   327→    };
   328→  }
   329→}
   330→
   331→/**
   332→ * Calculate the fine-tuning/caching threshold (θ̂)
   333→ * Users should cache only if their representative type θ > θ̂
   334→ */
   335→export function calculateCachingThreshold(modelName: string): number {
   336→  const params = MODEL_PARAMS[modelName];
   337→  const pricing = getPricingTier(modelName);
   338→  
   339→  if (!params) {
   340→    throw new Error(`Unknown model: ${modelName}`);
   341→  }
   342→
   343→  const { baseQuality, alphaParam, betaParam, gammaParam } = params;
   344→  const { inputCostPerMTok, outputCostPerMTok, cacheWriteCostPerMTok } = pricing;
   345→
   346→  // θ̂ = b^(1-α-β-γ) × (cx/α)^α × (cy/β)^β × (cz/γ)^(1-α-β)
   347→  const threshold = 
   348→    Math.pow(baseQuality, 1 - alphaParam - betaParam - gammaParam) *
   349→    Math.pow(inputCostPerMTok / alphaParam, alphaParam) *
   350→    Math.pow(outputCostPerMTok / betaParam, betaParam) *
   351→    Math.pow(cacheWriteCostPerMTok / gammaParam, 1 - alphaParam - betaParam);
   352→
   353→  return threshold;
   354→}
   355→
   356→/**
   357→ * Calculate quality metrics including marginal costs
   358→ */
   359→export function calculateQualityMetrics(
   360→  modelName: string,
   361→  tokenUsage: TokenUsage
   362→): QualityMetrics {
   363→  const params = MODEL_PARAMS[modelName];
   364→  const pricing = getPricingTier(modelName, tokenUsage.promptLength);
   365→  
   366→  if (!params) {
   367→    throw new Error(`Unknown model: ${modelName}`);
   368→  }
   369→
   370→  const cacheTokens = (tokenUsage.cacheWriteTokens || 0) + (tokenUsage.cacheReadTokens || 0);
   371→  const qualityScore = calculateQuality(
   372→    tokenUsage.inputTokens,
   373→    tokenUsage.outputTokens,
   374→    cacheTokens,
   375→    params
   376→  );
   377→
   378→  const cost = calculateCost(modelName, tokenUsage);
   379→  const costPerQualityUnit = cost.totalCost / qualityScore;
   380→
   381→  // Marginal cost = ∂C/∂X = c_x (cost to add one more token)
   382→  const marginalCostInput = pricing.inputCostPerMTok / 1_000_000;
   383→  const marginalCostOutput = pricing.outputCostPerMTok / 1_000_000;
   384→
   385→  return {
   386→    qualityScore,
   387→    costPerQualityUnit,
   388→    marginalCostInput,
   389→    marginalCostOutput,
   390→  };
   391→}
   392→
   393→// ============================================
   394→// PROJECTION FUNCTIONS
   395→// ============================================
   396→
   397→/**
   398→ * Project future costs based on historical usage
   399→ */
   400→export function projectCosts(
   401→  historicalCosts: number[],
   402→  daysToProject: number,
   403→  method: 'linear' | 'exponential' = 'linear'
   404→): number[] {
   405→  if (historicalCosts.length < 2) {
   406→    return Array(daysToProject).fill(historicalCosts[0] || 0);
   407→  }
   408→
   409→  const projections: number[] = [];
   410→
   411→  if (method === 'linear') {
   412→    // Linear regression
   413→    const n = historicalCosts.length;
   414→    const sumX = (n * (n - 1)) / 2;
   415→    const sumY = historicalCosts.reduce((a, b) => a + b, 0);
   416→    const sumXY = historicalCosts.reduce((sum, y, x) => sum + x * y, 0);
   417→    const sumX2 = (n * (n - 1) * (2 * n - 1)) / 6;
   418→
   419→    const slope = (n * sumXY - sumX * sumY) / (n * sumX2 - sumX * sumX);
   420→    const intercept = (sumY - slope * sumX) / n;
   421→
   422→    for (let i = 0; i < daysToProject; i++) {
   423→      const projected = intercept + slope * (n + i);
   424→      projections.push(Math.max(0, projected));
   425→    }
   426→  } else {
   427→    // Exponential smoothing
   428→    const alpha = 0.3;
   429→    let smoothed = historicalCosts[0];
   430→    
   431→    for (const cost of historicalCosts) {
   432→      smoothed = alpha * cost + (1 - alpha) * smoothed;
   433→    }
   434→
   435→    // Project forward with growth rate from last few points
   436→    const recentGrowth = historicalCosts.length > 1 
   437→      ? historicalCosts[historicalCosts.length - 1] / historicalCosts[historicalCosts.length - 2]
   438→      : 1;
   439→
   440→    for (let i = 0; i < daysToProject; i++) {
   441→      projections.push(smoothed * Math.pow(recentGrowth, i + 1));
   442→    }
   443→  }
   444→
   445→  return projections;
   446→}
   447→
   448→// ============================================
   449→// UTILITY FUNCTIONS
   450→// ============================================
   451→
   452→/**
   453→ * Format cost as currency string
   454→ */
   455→export function formatCost(cost: number): string {
   456→  return new Intl.NumberFormat('en-US', {
   457→    style: 'currency',
   458→    currency: 'USD',
   459→    minimumFractionDigits: 2,
   460→    maximumFractionDigits: 4,
   461→  }).format(cost);
   462→}
   463→
   464→/**
   465→ * Format token count with K/M suffix
   466→ */
   467→export function formatTokens(tokens: number): string {
   468→  if (tokens >= 1_000_000) {
