     1→/**
     2→ * Tokalator MCP Server
     3→ *
     4→ * Exposes real Claude BPE token counting and budget analysis to Claude Code.
     5→ * Uses stdio transport — all logging goes to stderr (stdout is reserved for JSON-RPC).
     6→ *
     7→ * Tools:
     8→ *  count_tokens    — Count tokens in text or a file
     9→ *  estimate_budget — Full budget breakdown for a list of files
    10→ *  preview_turn    — Preview estimated cost of next chat turn
    11→ *  list_models     — List available Claude model profiles
    12→ */
    13→
    14→import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
    15→import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
    16→// z is re-exported by tool schemas; keep dependency but remove unused direct import
    17→
    18→import { TokenizerService } from './core/tokenizerService.js';
    19→import { countTokens, countTokensSchema } from './tools/countTokens.js';
    20→import { estimateBudget, estimateBudgetSchema } from './tools/estimateBudget.js';
    21→import { previewTurn, previewTurnSchema } from './tools/previewTurn.js';
    22→import { listModels } from './tools/listModels.js';
    23→
    24→const tokenizer = new TokenizerService();
    25→
    26→const server = new McpServer({
    27→  name: 'tokalator',
    28→  version: '3.1.1',
    29→});
    30→
    31→// ── count_tokens ──────────────────────────────────────────────────────────────
    32→
    33→server.registerTool(
    34→  'count_tokens',
    35→  {
    36→    description: 'Count tokens in a text string or file using the real Claude BPE tokenizer. Provide either `text` or `file` (path).',
    37→    inputSchema: countTokensSchema,
    38→  },
    39→  async (input) => {
    40→    const result = await countTokens(input, tokenizer);
    41→    return { content: [{ type: 'text', text: result }] };
    42→  },
    43→);
    44→
    45→// ── estimate_budget ───────────────────────────────────────────────────────────
    46→
    47→server.registerTool(
    48→  'estimate_budget',
    49→  {
    50→    description: 'Estimate the token budget for a set of files plus conversation overhead. Returns a full breakdown: files, system prompt, instructions, conversation, and output reservation.',
    51→    inputSchema: estimateBudgetSchema,
    52→  },
    53→  async (input) => {
    54→    const result = await estimateBudget(input, tokenizer);
    55→    return { content: [{ type: 'text', text: result }] };
    56→  },
    57→);
    58→
    59→// ── preview_turn ──────────────────────────────────────────────────────────────
    60→
    61→server.registerTool(
    62→  'preview_turn',
    63→  {
    64→    description: 'Preview the estimated token cost of the next chat turn. Shows current usage, projected usage after the turn, and how many turns remain before hitting the context limit.',
    65→    inputSchema: previewTurnSchema,
    66→  },
    67→  async (input) => {
    68→    const result = previewTurn(input);
    69→    return { content: [{ type: 'text', text: result }] };
    70→  },
    71→);
    72→
    73→// ── list_models ───────────────────────────────────────────────────────────────
    74→
    75→server.registerTool(
    76→  'list_models',
    77→  {
    78→    description: 'List all available Claude model profiles with context window sizes, max output tokens, and context rot thresholds.',
    79→    inputSchema: {},
    80→  },
    81→  async () => {
    82→    const result = listModels();
    83→    return { content: [{ type: 'text', text: result }] };
    84→  },
    85→);
    86→
    87→// ── Start ─────────────────────────────────────────────────────────────────────
    88→
    89→const transport = new StdioServerTransport();
    90→await server.connect(transport);
    91→console.error('[tokalator-mcp] Server ready — Claude BPE tokenizer loaded on first use');
    92→

