     6→// Module-level reference so deactivate() can save session
     7→let monitorRef: ContextMonitor | undefined;
     8→
     9→function fmtTokens(n: number): string {
    10→  if (n >= 1_000_000) return (n / 1_000_000).toFixed(1) + 'M';
    11→  if (n >= 1_000) return (n / 1_000).toFixed(1) + 'K';
    12→  return n.toString();
    13→}
    14→
    15→function formatTimeAgo(iso: string): string {
    16→  const ms = Date.now() - new Date(iso).getTime();
    17→  const mins = Math.floor(ms / 60_000);
    18→  if (mins < 60) return `${mins}m ago`;
    19→  const hours = Math.floor(mins / 60);
    20→  if (hours < 24) return `${hours}h ago`;
    21→  const days = Math.floor(hours / 24);
    22→  return `${days}d ago`;
    23→}
    24→
    25→/**
    26→ * Tokalator - Count your tokens like beads on an abacus.
    27→ *
    28→ * Activates:
    29→ *  1. ContextMonitor — core engine tracking editor state
    30→ *  2. ContextDashboardProvider — sidebar webview panel
    31→ *  3. ContextChatParticipant — @tokalator chat commands
    32→ *  4. Commands — refresh, optimize, clearPins
    33→ */
    34→export async function activate(context: vscode.ExtensionContext): Promise<void> {
    35→
    36→  // 1. Core monitor (with persistence for pinned files)
    37→  const monitor = new ContextMonitor(context.workspaceState);
    38→  monitorRef = monitor;
    39→  context.subscriptions.push(monitor);
    40→
    41→  // 2. Sidebar dashboard
    42→  const dashboardProvider = new ContextDashboardProvider(context.extensionUri, monitor);
    43→  context.subscriptions.push(
    44→    vscode.window.registerWebviewViewProvider(
    45→      ContextDashboardProvider.viewType,
    46→      dashboardProvider,
    47→    ),
    48→  );
    49→
    50→  // 3. Chat participant
    51→  const chatParticipant = new ContextChatParticipant(monitor);
    52→  context.subscriptions.push(chatParticipant);
    53→
    54→  // 4. Commands
    55→  context.subscriptions.push(
    56→    vscode.commands.registerCommand('tokalator.refresh', () => {
    57→      monitor.refresh();
    58→    }),
    59→  );
    60→
    61→  context.subscriptions.push(
    62→    vscode.commands.registerCommand('tokalator.optimize', async () => {
    63→      const closed = await monitor.optimizeTabs();
    64→      if (closed.length > 0) {
    65→        vscode.window.showInformationMessage(
    66→          `Closed ${closed.length} low-relevance tabs: ${closed.join(', ')}`,
    67→        );
    68→      } else {
    69→        vscode.window.showInformationMessage('All tabs are relevant — nothing to close');
    70→      }
    71→    }),
    72→  );
    73→
    74→  context.subscriptions.push(
    75→    vscode.commands.registerCommand('tokalator.clearPins', () => {
    76→      monitor.clearPins();
    77→      vscode.window.showInformationMessage('All pinned files cleared');
    78→    }),
    79→  );
    80→

